def transform(grid):
    """Fill hollow square interiors: odd-width interiors become 7, even become 2."""
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0]) if h else 0
    fills=[]
    # Find square frames with a solid, uniform border and a uniform contrasting interior.
    for side in range(3, min(h,w)+1):
        inner=side-2
        color=7 if inner % 2 else 2
        for r in range(h-side+1):
            for c in range(w-side+1):
                border=g[r][c]
                if any(g[r][x] != border for x in range(c,c+side)):
                    continue
                if any(g[r+side-1][x] != border for x in range(c,c+side)):
                    continue
                if any(g[y][c] != border or g[y][c+side-1] != border for y in range(r,r+side)):
                    continue
                inside=g[r+1][c+1]
                if inside == border:
                    continue
                if all(g[y][x] == inside for y in range(r+1,r+side-1) for x in range(c+1,c+side-1)):
                    fills.append((r,c,side,color))
    for r,c,side,color in fills:
        for y in range(r+1,r+side-1):
            for x in range(c+1,c+side-1):
                g[y][x]=color
    return g
